import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  Loading,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import transportApi from "../../../api/transport/transportApi";
import { Modal } from "antd";
import CustomTextArea from "../../../components/forms/CustomTextArea";

export default function DestinationsFormModal({
  ismodalOpen,
  setisModalOpen,
  destination,
  modalTitle = "Add new destination",
  updated,
  setUpdated,
}) {


  const transportActionsApi = useApi(transportApi.transportAction);

  //Routes
  const [routes, setRoutes] = useState([]);
  const getRoutesActionsApi = useApi(transportApi.transportAction);
  const getRoutes = async () => {
    await getRoutesActionsApi.request({
      action: "GetEntityRoutes",
    });
  };

  useEffect(() => {
    getRoutes();
  }, []);

  useEffect(() => {
    if (getRoutesActionsApi.data && getRoutesActionsApi.data.length) {
      setRoutes(
        getRoutesActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }

    console.log("getRoutesActionsApi.data", getRoutesActionsApi.data);
  }, [getRoutesActionsApi.data]);

  const [errors, setErrors] = useState();

  const handleRouteAction = async (data) => {
    console.log("data at", data);
    const result = await transportActionsApi.request(data);

    if (result.ok) {
      console.log("res", result);
      setUpdated(true);
      setisModalOpen(false);
    } else {
      setUpdated(false);
    }
  };

  useEffect(() => {
    if (transportActionsApi.data) {
      setisModalOpen(false);
      // if (transportActionsApi.data.destination) {
      //     setDestination(transportActionsApi.data.destination)
      // }

      if (transportActionsApi.data.errors) {
        setErrors(transportActionsApi.data.errors);
      }
    }

    console.log("transportActionsApi.data", transportActionsApi.data);
  }, [transportActionsApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const formik = useFormik({
    initialValues: {
      route: destination
        ? { label: destination.route_title, value: destination.route }
        : "",
      destination_from: destination ? destination.destination_from : "",
      destination_to: destination ? destination.destination_to : "",
      fare: destination ? destination.fare : "",
      fare_peak: destination ? destination.fare_peak : "",
      description: destination ? destination.description : "",
    },

    validationSchema: Yup.object({
      destination_from: Yup.string()
        .min(3, "Must be 15 characters or more")
        .required("Origin is required"),
      destination_to: Yup.string()
        .min(3, "Must be 3 characters or more")
        .required("Destination is required"),
      fare: Yup.number()
        .min(0, "Must be 3 characters or more")
        .required("Fare at off peak is required"),
      fare_peak: Yup.number()
        .min(0, "Must be 3 characters or more")
        .required("Fare at peak time is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      if (destination) {
        handleRouteAction({
          action: "UpdateDestination",
          destination_details: {
            destination_id: destination.id,
            route_id: values.route.value,
            destination_from: values.destination_from,
            destination_to: values.destination_to,
            fare: values.fare,
            fare_peak: values.fare_peak,
            description: values.description ? values.description : "",
          },
        });
      } else {
        handleRouteAction({
          action: "CreateDestination",
          destination_details: {
            destination_from: values.destination_from,
            destination_to: values.destination_to,
            fare: values.fare,
            fare_peak: values.fare_peak,
            description: values.description ? values.description : "",
            route_id: values.route.value,
          },
        });
      }

      // resetForm();
    },
  });

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  return (
    <div className="w-full">
      <Modal
        width={560}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.route}
            error={formik.errors.route}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="route"
              id="route"
              label="Select route"
              size="large"
              onChange={(value) => formik.setFieldValue("route", value)}
              value={formik.values.route}
              placeholder="Select route"
              options={routes}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.destination_from}
            error={formik.errors.destination_from}
          >
            <CustomInput
              required={true}
              id="destination_from"
              name="destination_from"
              onChange={formik.handleChange}
              placeholder="Enter destination from"
              size="large"
              type="text"
              value={formik.values.destination_from}
              label="Enter destination from"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.destination_to}
            error={formik.errors.destination_to}
          >
            <CustomInput
              required={true}
              id="destination_to"
              name="destination_to"
              onChange={formik.handleChange}
              placeholder="Enter destination to place"
              size="large"
              type="text"
              value={formik.values.destination_to}
              label="Enter destination to place"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.fare}
            error={formik.errors.fare}
          >
            <CustomInput
              required={true}
              id="fare"
              name="fare"
              onChange={formik.handleChange}
              placeholder="Enter off peak fare"
              size="large"
              type="number"
              value={formik.values.fare}
              label="Enter off peak fare"
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.fare_peak}
            error={formik.errors.fare_peak}
          >
            <CustomInput
              required={true}
              id="fare_peak"
              name="fare_peak"
              onChange={formik.handleChange}
              placeholder="Enter peak fare"
              size="large"
              type="number"
              value={formik.values.fare_peak}
              label="Enter peak fare "
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.description}
            error={formik.errors.description}
          >
            <CustomTextArea
              required={true}
              id="description"
              name="description"
              onChange={formik.handleChange}
              placeholder="Enter short description of the subscription"
              size="large"
              type="text"
              rows={2}
              value={formik.values.description}
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
